  name              = "Grafana"
  slug              = "grafana"
  protocol_provider = authentik_provider_oauth2.grafana.id

  meta_icon        = "https://grafana.com/static/assets/img/fav32.png"
  meta_description = "Observability dashboards and visualization"
  meta_publisher   = "Homelab"
  meta_launch_url  = "https://grafana.${var.domain_internal}"

  # Open to all authenticated users
  policy_engine_mode = "any"
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "grafana_oidc_issuer_url" {
  description = "OIDC issuer URL for Grafana"
  value       = "https://auth.${var.domain_public}/application/o/grafana/"
}

output "grafana_oidc_client_id" {
  description = "OIDC client ID for Grafana"
  value       = authentik_provider_oauth2.grafana.client_id
}

output "grafana_oidc_client_secret" {
  description = "OIDC client secret for Grafana"
  value       = random_password.grafana_oidc_secret.result
  sensitive   = true
}

